interface ValidationRule {
  validate(data: any): Promise<string | null>;
  setNext(rule: ValidationRule): ValidationRule;
}

abstract class BaseValidationRule implements ValidationRule {
  protected nextRule: ValidationRule | null = null;

  setNext(rule: ValidationRule): ValidationRule {
    this.nextRule = rule;
    return rule;
  }

  async validate(data: any): Promise<string | null> {
    const error = await this.validateRule(data);
    if (error) return error;

    if (this.nextRule) {
      return await this.nextRule.validate(data);
    }

    return null;
  }

  protected abstract validateRule(data: any): Promise<string | null>;
}

class EmailValidationRule extends BaseValidationRule {
  protected async validateRule(data: any): Promise<string | null> {
    if (!data.email) return 'Email is required';
    if (!data.email.includes('@')) return 'Invalid email format';
    return null;
  }
}

class PasswordValidationRule extends BaseValidationRule {
  protected async validateRule(data: any): Promise<string | null> {
    if (!data.password) return 'Password is required';
    if (data.password.length < 8) return 'Password must be at least 8 characters';
    return null;
  }
}

