enum LessonState {
  LOCKED = 'LOCKED',
  AVAILABLE = 'AVAILABLE',
  IN_PROGRESS = 'IN_PROGRESS',
  COMPLETED = 'COMPLETED'
}

interface State {
  start(): void;
  complete(): void;
  reset(): void;
}

class LockedState implements State {
  constructor(private lesson: Lesson) {}

  start() { throw new Error('Lesson is locked'); }
  complete() { throw new Error('Cannot complete locked lesson'); }
  reset() { }
}

class AvailableState implements State {
  constructor(private lesson: Lesson) {}

  start() {
    this.lesson.setState(new InProgressState(this.lesson));
  }
  complete() { throw new Error('Must start lesson first'); }
  reset() { }
}

class InProgressState implements State {
  constructor(private lesson: Lesson) {}

  start() { throw new Error('Lesson already started'); }
  complete() {
    this.lesson.setState(new CompletedState(this.lesson));
  }
  reset() {
    this.lesson.setState(new AvailableState(this.lesson));
  }
}

class CompletedState implements State {
  constructor(private lesson: Lesson) {}

  start() { }
  complete() { throw new Error('Lesson already completed'); }
  reset() {
    this.lesson.setState(new AvailableState(this.lesson));
  }
}

class Lesson {
  private state: State;

  constructor() {
    this.state = new LockedState(this);
  }

  setState(state: State) {
    this.state = state;
  }

  start() { this.state.start(); }
  complete() { this.state.complete(); }
  reset() { this.state.reset(); }
}

interface CourseComponent {
  getName(): string;
  getDuration(): number;
  getDescription(): string;
}

class Lesson implements CourseComponent {
  constructor(
    private name: string,
    private duration: number,
    private description: string
  ) {}

  getName() { return this.name; }
  getDuration() { return this.duration; }
  getDescription() { return this.description; }
}

class Section implements CourseComponent {
  private components: CourseComponent[] = [];

  constructor(private name: string) {}

  addComponent(component: CourseComponent) {
    this.components.push(component);
  }

  removeComponent(component: CourseComponent) {
    const index = this.components.indexOf(component);
    if (index > -1) this.components.splice(index, 1);
  }

  getName() { return this.name; }
  getDuration() {
    return this.components.reduce((sum, c) => sum + c.getDuration(), 0);
  }
  getDescription() {
    return `${this.components.length} lessons`;
  }
}

class Course implements CourseComponent {
  private sections: Section[] = [];

  constructor(private name: string) {}

  addSection(section: Section) {
    this.sections.push(section);
  }

  getName() { return this.name; }
  getDuration() {
    return this.sections.reduce((sum, s) => sum + s.getDuration(), 0);
  }
  getDescription() {
    return `${this.sections.length} sections, ${this.getDuration()} hours`;
  }
}

